it('answers an immediate session list before the following ping', async () => {
  // spec: specs/hal-engine-conversation-list/spec.md#42
  const disconnected = deferred();
  const {url} = await startEngineWith({
    sessionStore: new InMemorySessionStore(),
    onDisconnect: disconnected.release,
  });
  const client = connectClient(url);
  const frames = await new Promise<string[]>(resolve => {
    const seen: string[] = [];
    client.on('message', raw => {
      const {type} = JSON.parse(String(raw)) as {type: string};
      if (type === 'connected') {
        client.send(JSON.stringify({type: 'list_sessions'}));
        client.send(JSON.stringify({type: 'ping', timestamp: 1}));
        return;
      }
      seen.push(type);
      if (type === 'pong') resolve([...seen]);
    });
  });
  await new Promise<void>(resolve => {
    client.once('close', () => resolve());
    client.close();
  });
  await disconnected.until;
  expect(frames).toEqual(['session_list', 'pong']);
});
